            "id": "sy002",
            "title": "二、考试要求",
            "summary": "二、考试要求",
            "body": [
              "成人高等教育非英语专业学士学位英语水平考试要求考生能够较",
              "用能力。考生在运用能力方面应分别达到以下要求：",
              "（一）会话",
              "能够使用英语进行日常会话交流，根据对话的情景、场合、人物关",
              "系、身份和讲话人的意图及话语含义做出正确判断和用语选择，并能理",
              "解常见的英语口语的习惯用法。",
              "（二）阅读",
              "能够综合运用英语知识和基本阅读技能，读懂难度适中的一般性",
              "题材（经济、社会、政法、历史、科普、管理等）和体裁（记叙文、议论文、说",
              "明文、应用文等）的英语文章。阅读速度达到每分钟80个词。具体要",
              "求为：",
              ".1.",
              "1.能够掌握文章的中心思想、主要内容和细节；",
              "2.具备根据上下文把握词义的能力，理解上下文的逻辑关系；",
              "3.能够根据所读材料进行一定的推论；",
              "4.能够对文章的结构和作者的态度等做出一般的分析和判断。",
              "（三）词汇",
              "掌握本考试大纲所规定的英语词汇、常用词组、常用词缀，并在阅",
              "读、写作等过程中具有相应的应用能力，即：",
              "1.领会式掌握4400个单词和550个常用词组；",
              "2.复用式掌握2000个左右的常用单词和搭配以及200个左右的",
              "常用词组；",
              "3.掌握一定数量的常用词缀，并能根据构词法和语境识别常见的",
              "派生词。",
              "（四）语法",
              "掌握基本的英语语法知识，要求能在阅读、写作等过程中正确运用",
              "这些知识，达到正确理解、获取信息及表达思想的自的。需要掌握的具",
              "体内容如下：",
              "1.名词、代词的数和格的构成及其用法；",
              "2.动词的基本时态、语态的构成及其用法；",
              "3.形容词、副词的比较级和最高级的构成及其用法；",
              "4.常用连接词、冠词的词义及其用法；",
              "5.非谓语动词（不定式、动名词、分词）的构成及其用法；",
              "6.虚拟语气的构成及其用法；",
              "7.各类从句的构成及其用法；",
              "8.基本句型的结构及其用法；",
              "9.强调句型的结构及其用法；",
              "10.常用倒装句的结构及其用法。",
              ".2.",
              "（五）翻译",
              "能够在不借助词典的情况下把一般难度、非专业性题材的英文句",
              "子或短文译成汉语，译文通顺，用词基本正确，无重大语法错误。英译",
              "汉的速度应达到每小时250词以上。",
              "（六）写作",
              "能够用英语撰写常见应用文，或能够按照所给提纲、情景或图表，",
              "说明或论述一般性的话题。所写短文要求主题明确，条理清楚，语言比",
              "较规范。"
            ]
