              "Before recruiting, think carefully about how many people you",
              ":8:",
              "want to participate and also what the club's focus will be.For example,",
              "some book clubs focus exclusively on fiction, others on nonfiction.",
              "Some are even more specific, focusing only on a particular type such",
              "as mysteries, science fiction, or romance. Others have a more",
