              "Passage Two",
              "The Mayan(玛雅）Indians lived in Mexico for thousands of years",
              "before the Spanish arrived in the 15oos. The Maya were an",
              "intelligent, culturally rich people whose achievements were many.",
              "They had farms, beautiful palaces, and cities with many buildings.",
              "The Mayan people knew a lot about nature and the world around",
              "them. This knowledge helped them to live a better life than most",
              "people of that time, because they could use it to make their lives",
              "more comfortable and rewarding. Knowledge about tools and",
              "farming, for instance, made their work easier and more productive.",
              "The Maya believed in many gods, including rain gods, sun gods,",
              "and corn gods. The people built large temples to honour them. Skillful",
