              "翻译—这里还仅仅是英译汉——需要理解精准，比阅读理解的要求更高。没有准确的理",
              "解就不会有正确的表达，而准确的理解依靠平时练就的功夫。翻译中由于词义或语法理解错误",
              "而导致的表达错误比比皆是。现举一例：",
              "(1) Each plant and animal tends to produce far more seeds, eggs, and young than is necessary to",
