              "本句中的egg和population都是基本单词，大部分考生熟悉的意义分别是“蛋”和“人口”。",
              "确的解读，因此他们有可能不假思索就按自己熟悉的意义翻译这两个词，结果自然是错误的。因",
              "为“蛋”只是较大的“卵”，大量的鱼卵不能称之为“蛋”，但都是egg。至于把population译成“人",
              "口”，就更不准确了，因为population不仅是“人口”，还是广义的“动物或植物的数量”。本句试",
              "译如下：",
              "“每一种动植物所产种子、卵、或幼仔往往多于维持其本身数量的需要。”",
