            "body": [
              "再看句子结构的分析。在句子结构比较复杂的情况下，句法分析的过程不可忽略。考生要",
              "关注3点：句子基本结构、“陷式”句型及句型的变化。",
              "一是厘清句子基本结构。一般来说，一个完整句子必须主谓齐全，而且，除非有并列连接词",
              "连接，不能出现两个或两个以上的主语和谓语，即如果一个句子中出现没有并列连接词的两个或",
              "两个以上谓语动词，则可能是从句。例如：",
              "(9) The rate at which man has been storing up useful knowledge about himself and the universe",
              "has been spiraling upward for 10, 000 years.",
              "从理解角度看，本句句法分析重点有三：一是句子的主干成分，即主语和谓语动词是什么？",
              "二是以atwhich引导的定语从句到哪里为止？三是介词about的宾语只有himself还是同时还包",
              "括theuniverse?",
              "应该说，提出这3个问题本身就是厘清句法成分的过程。首先，主干成分为Therate··．has",
              "beenspiralingupward；其次，atwhich引导的定语从句从man到universe；第三，about包括了",
              "himself和theuniverse两个宾语。这样，结合中文状语在前的表达习惯以及上文关于代词和动词",
              "形式的处理方法，本句可译成：",
              "“过去一万年以来，人类在了解自身、了解宇宙过程中获得了许多有用的知识，这种知识增",
              "长的速度呈递增趋势。”",
              "(10) You will be informed when they will leave for New York.",
              "这个句子译成“他们出发去纽约时会通知你”还是，",
              "“他们何时动身去纽约会通知你”？",
              "这需要对从句whentheywillleaveforNewYork做句法分析。前一句译文显然是一看到",
              "when，就不假思索把它和后面的小句当成了时间状语从句的结果。但是，如果语法概念比较清",
              "楚，就应该知道，时间状语从句中不能出现将来时态。所以，从will leave就应能判断when引导",
              "的不是状语从句，而是宾语从句，因此，后一个译文理解正确。",
              "二是留意“陷阱式”句型。陷阱式句型就是那种稍不留意就会看错的句型。例如：",
              "(11)The mountain is not valued because it is high.",
              "(12) Tom and Rose did not get married out of love.",
              "这两个句子句式相似，都与否定辖域有关，即否定覆盖到哪里。第一句如果把否定看作到",
              "valued为止，则可译为“这座山因为太高而无法估量其价值”，这似乎不合常理。如果把否定延",
              "伸至句末，即notvaluedbecauseitishigh，全句意思就变成“山不以它的高度衡量价值”。更精炼",
              "的译文可以是：“山不在高。”",
              "第二句同理。否定如到married为止，可译成“他俩出于相爱而没有结婚”，这似乎荒谬。如",
              "把否定延伸到句末，则译文可为“汤姆和露丝并非出于爱情才结婚。”这才符合情理。",
              "三是要警惕一些句型的变体。例如：",
              "(13) We have found that these conditions have drawn to one type of activity or the other many",
              "men who have had special training.",
              "如果能够看出这是动词结构drawsb.tosth.的变体，本句就不难理解。由于sb.（manymen）",
              "后还跟了一个定语从句，为避免句式松散，本句将动词结构中的to sth.提到了sb.之前。考生需",
              "要仔细辨别，以免出错。本句可译成：",
              "62>>>第二部分考试指南",
              "“我们发现，这些条件吸引了许多受过专门训练的人来从事这样那样的活动。”",
              "3.解读句中蕴含的文化含义",
              "文化诠释是翻译理解的又一个方面，大致可分为两种情况，一是所谓“文化套句”，二是所谓",
              "“文化词语”，两者都要求考生具有文化敏感性。",
              "文化套句乍一看很平常，但实际上却是一种固定句式，具有特定含义，表达特定信息。常规",
              "翻译可能会不得要领或不知所云。例如：",
              "(14) a.We went away as wise as we came.",
              "b.Your guess is as good as mine.",
              "我一样好”就都违背了原句意思。实际上，两句都属于文化套句，有着特定含义，即：",
              "“我们走的时候和来的时候一样，结果一无所获。”",
              "“你同我一样没猜对。”",
              "然而在翻译中遇到文化词语的情况则更为经常。文化词语的来源多种多样：宗教信仰、自然",
              "环境、风土人情、价值观念、社会制度、生产生活方式、神话传说、认知方式，等等。例如：",
              "(15) Joanna took the news about the rise in price of edible oil with a grain/pinch of salt.",
              "“乔安娜对食用油价格上涨的消息半信半疑。”",
              "(16) Bert passed the spoken language test by the skin of his teeth.",
              "by/withtheskinofone'steeth是源自典故的口语表达，意为“差点没”、“刚好”、“好不容易",
              "才”、“勉强”，因此本句可译为：",
              "“伯特勉强通过了口语考试。”",
              "文化套句和文化词语的理解和翻译原来是翻译中的一大难点，但随着网络的普及，文化套句",
              "和词语的解读障碍大大降低，只要我们有足够的文化意识，多查阅多记忆，天部分文化问题就可",
              "以迎刃而解。",
              "4.厘清句中和句间的逻辑关系",
              "厘清逻辑关系部分属于语法分析，但还包括篇章层面的分析。这里谈3个方面：时间顺序、",
              "逻辑分类和逻辑指代。",
              "第一，时间顺序。从英语“先主后从、重心在前”和汉语“先偏后正、重心在后”的差异，要求",
              "先进行动作时间顺序的分析，以确定从哪里落笔进行翻译。例如：",
              "(17) This morning I came back by train from Beijing where I had visited some of my former",
              "colleagues after I had completed my task.",
              "本句从时间顺序分析，第一个完成的动作是completedmytask，接着完成visitedsomeofmy",
              "formercolleagues，最后才是cameback，所以句子本身的顺序同动作实际发生的先后完全颠倒，因",
              "而宜采取倒译的方法，才能符合汉语的组句习惯：",
              "“我在北京办完事后，去看了几位老同事，今天早晨坐火车回来的。”",
              "(18)I ②was just walking out of the local library,having unsuccessfully sought employment",
              "there, when I saw a man walking across the road with the obvious intension of talking to me.",
              "本句将最先发生的动作通过现在分词的完成体放到了第一个动作和第三个动作中间，翻译"
            ]
