              "例如：",
              "(19) Automobiles and trucks would be powered by quickly replaceable electric batteries.",
              "由于automobile是一个熟悉的词，很多初译者容易将作为本句主语的两个并列名词",
              "automobilesand trucks不假思索译成“汽车和卡车”，殊不知“卡车”也是“汽车”！所以这个翻译",
              "没有理清其中蕴含的逻辑关系，掉进了逻辑陷阱。正确的译法是：",
              "“轿车和卡车的动力将由可快速更换的电池提供。”",
              "(20)Our eyes can only see clearly an object of 1mm.Beyond 1mm milestone,we need an",
              "amplifying glass.",
              "本句中的beyond如果只译为“超过”，会造成语义不清，甚至出现歧义，应根据上一句提供的",
              "语境，结合常识，将其所表达的分类关系作显性化处理，译为“以下”：",
              "“我们的眼睛只能看清1毫米以上的东西，要看1毫米以下的东西，只能借助放大镜。”",
              "第三，逻辑指代。翻译前有必要厘清句间逻辑指代关系。例如：",
              "(21) Indeed, rarely were these regular orders cancelled, and in bad weather they formed a steady",
              "source of income.In the evening they solve an awkward problem, as usual selling, even I kept to the",
              "customary arrival times, needed some sort of notice to be given that I was outside with the van.",
              "这个由两个句子构成的小段说的是一名高中毕业生在从毕业后到上大学前的一段时间内卖",
              "冰棍的情形。有两个逻辑指代关系需要明确，一个是画线的这两个they指什么？另一个是an",
              "awkwardproblem指什么？从上下文看，画线的两个they都指上文的theseregularorders；而an",
              "awkwardproblem则指由连词as引导的从句中的neededsomesortofnoticetobegiven。该从句从",
              "语法上看，是一个表示原因的时间状语，却从意义上解释了这个problem，即“需要想办法让人知",
              "道我的冰棍车来了”。整句可译成：",
              "“实际上，这种常规订货很少取消。天气不好时，这些订购成了我稳定的收入来源；天黑时，",
              "这些订货解决了一个难题，因为通常的零星销售，即使我在人们习惯的时候到达那些小区，也需",
              "要想办法让人知道我的冰棍车来啦。”",
              "（二）表达通顺是关键",
              "对词义、语法、文化和逻辑4个方面的准确理解和分析为译文的通顺表达提供了必要的前提",
              "和条件。简单地说，译文的通顺表达大致可从两个方面加以描述：措辞准确搭配地道、句法规范",
              "逻辑清楚。",
              "1.措辞准确搭配地道",
              "有时候，词义和句意理解并不困难，但表达起来却颇费跨踏。例如：",
              "(22)He always lives ahead of his salary.",
              "这样的句子在阅读理解时，可以说一目了然，但要用中文写出来，却并不那么容易。译成",
              "“他的生活开销总是超过他的工资收人”基本可以，但稍嫌啰唆；写成“他总是人不敷出”，属于套",
              "用中文熟语，乍一看有所升华，但效果上略显陈词滥调；编者以为，“他花钱总比挣钱快”应该算",
              "64>>>第二部分考试指南",
              "是比较鲜活的翻译。当然从考试角度看，前两个翻译都应该视为正确。",
              "但请看下例：",
              "(23)A ①major study found that the ②positive-thinkers among ③longtime representatives sold",
              "37% more insurance than did the @negative-thinkers. Of newly hired representatives, optimists sold",
              "scored high on optimism. These people, who might never have been hired, sold 10% more insurance",
              "than did the average representatives.",
              "本例中画线的5个词major、longtime、positive/negative和impressed，如果都按照词典释义机",
              "械照搬，则整个译文将十分晦涩。实际上，在翻译过程中，一个词的含义确定后，应根据其“左邻",
              "右舍”确定其具体表述，此所谓“搭配地道”。在本例语境中，根据搭配，major study、longtime",
              "representatives和positive/negative-thinkers应分别译成“重大研究项目”、“资深销售代表”和“性",
              "格乐观/悲观者”。至于impressed，如果写成“印象深刻”，同样会给人似懂非懂的感觉，根据上下",
              "文，可译成“有感于此”。据此，以上小段可译为：",
              "“一项重大研究项目发现，在资深的保险销售代表中，性格乐观者比悲观者的销售额高出",
