              "(24) The bridge was so well built that it lasted a thousand years.",
              "很多初译者会因为词典中将so..that..解释为“如此.以至于...”而顺手将这样的",
              "句子译为：",
              "“这座桥造得如此牢固以至于它持续了1000年。”",
