              "is worthwhile and respected.  Such people find their work intrinsically interesting and satisfying.",
              "习作者提供的译文是：",
              "“①马斯洛把自我实现的需要定义为“要求成为一个比现状更好的人，一个实现自已有能力",
              "达到的人”。②在这种水平上生活的人，通常认为自已工作就是要做的某种事情，其目的就是要",
