              "【解析】本句看似简单，但有两个英语熟语，runsb．intotheground和amatterof，前者意为",
              "“打败某人”，后者表示“仅仅、仅需”。这两个短语一旦明确，整句翻译即可迎刃而解。",
              "【参考译文】“这样循环往复，不出几代，我们的国家将趋于毁灭。”",
              "如果“文艺”一点，本句还可译为：“长此以往，则不出几代，我们势必国将不国。”",
              "通过以上练习，有两点需要提醒考生。一是，画线句子翻译同段落全文翻译的区别在于，它",
              "及其余；二是，看似简单的词和句子尤其要多加小心，避免因不假思索而出现不该出现的错误，本",
              "段中以第[4]句的grows最为典型。",
              "【练习二】将下面的短文译成中文。",
              "[1] English food has a bad reputation abroad. [2] This is most probably because foreigners in",
              "England are often obliged to eat in the more \"popular\" type of restaurant. [3] Here it is necessary to",
              "prepare food rapidly in large quantities, and the taste of the food inevitably suffers,though its quality",
              "from the point of view of nourishment, is quite satisfactory.[4] Still, it is rather dull and not always",
              "attractively presented.[5] Moreover, the Englishman eating in a cheap or medium price restaurant is",
              "usually in a hurryat least at lunch-and a meal eaten in a leisurely manner in pleasant surroundings",
              "is always far more enjoyable than a meal taken hastily in a business-like atmosphere.",
              "【解析及参考译文】",
              "本段共114个英文单词，分成5句，平均句长22.8个词，摘自吕志鲁《翻译应试指南》中英语",
              "专业八级考试的一段翻译练习。结构复杂程度以及词汇难度接近于成人学士学位考试，只是",
              "[3]、[5]两句较长，分别达32和45个词。",
              "72>>>第二部分考试指南",
              "译文一（http：//blog.sina.com.cn/s/blog_6a7f8ee10100tw9g.html)",
              "“在英格兰，外来人们总是不得不到更加大众化的快餐店就餐，这很可能是英国食物在国",
              "外声名不佳的原因。在这里，厨师们需在短时间内烹调大量食物，如此一来，食物的味道难免",
              "会大打折扣，但从营养的角度来讲，它们的品质还算差强人意。然而，食物的呈献并不总显得",
              "多么诱人，反之，它们相当单调，令人厌烦。此外，英国人在中低档餐馆用餐时通常都很匆忙，",
              "至少午餐时间是如此，但悠闲自在地在舒适的环境里就餐远比为公事匆忙就餐来得惬意吧？”",
              "(202字）",
              "译文二（吕志鲁：《翻译应试指南》，武汉大学出版社2005年版，第116～117页）",
              "“英国食品在海外的名声不好。这很可能是因为去英国的外国人不得不常在更“大众化”的",
              "餐馆里用餐的缘故。在那里，必须大量迅速地备餐，因此饭菜的味道必然逊色，尽管在营养方面，",
              "饭菜质量还是令人满意的，可是饭菜仍然显得单调，颜色花样也常常不大讲究。此外，在价钱便",
              "宜或者适中的饭店里用餐的英国人，通常是来去匆匆一一至少午餐是如此一而在舒适环境中",
