              "相比之下，译文二比译文一稍短，有些词句的处理存在明显差异，这也是翻译千人面的普",
              "遍规律，只有更好，没有最好。以下对两个译文中若干词的不同理解和表述以及对句法的不同处",
              "理做一简单比较，以帮助考生加强理解和表达的精到性训练。",
              "译文一和二对[1]、[2]两句的顺序处理显然相反，前者采取倒译，后者采用顺译；措辞基本",
              "相同，只是foreigners一个译为“外来人”，一个译为“外国人”。在编者看来，English food译为“英",
              "国食物（食品）”似有概念扩大之嫌，因为“食物”、“食品”远不止本文所指的餐馆菜肴；areobliged",
              "to译成“不得不”有点翻译腔。所以前两句试改译为：",
              "[1］“英国餐馆的菜肴在海外名声不好，”",
              "第[3]句中的here,译文一译为“这里”，译文二译为“那里”都不明确，应该明确这个here指",
              "的是前一句的themore“popular”typeof restaurant，且在译文中予以明晰。综合两种译文，该句",
              "可改译为：",
              "[3］“在这种餐馆，厨师需在很短时间内做出很多菜品，因此，这些菜品尽管从营养角度看",
              "品质差强人意，但味道必然受到影响。”",
