              "其次是篇章结构知识的备考。考生应该关注一下有关文章结构的知识，知晓一般应用文、说",
              "明文和论述文的常规格式和常规写法，如开篇、发展、结尾、起承转合等。",
              "顺便说一下，前面这两个方面，可参考的资源很多，尤其是网络资源，十分丰富，比如互联网",
              "上有许多作文题目、各种范文，甚至提供了带空格的各类作文模板。但考生要小心了，这些材料",
              "很多是粗制滥造的，知识介绍错误频出，英语不堪卒读，切不可当做应试宝典顶礼膜拜。",
              "最后，也是最重要的是，备考写作，考生务必首先提高自已的英语运用能力。写作不同于阅",
