              "In our modern society, communication between people is often attached of great importance.",
              "Interaction or communication is of vital position in our routine life.",
              "Through communicating with others, we can better understand what he or she thinks, which will",
              "better further contact between each other.Mutual trust can be formed on the basis of mutual",
              "82>>>第二部分考试指南",
              "interaction. For example, someone cannot build a good friendship with people around who he or she",
              "may not understand well at first. However, through communication, the real thought between each",
              "other may be found and the common interest could be found, which wil be beneficial for developing",
              "the relationship.",
              "In additional, some disputes and misunderstanding could be settled through communication.We",
              "could have a good judgment about the issue or matter after knowing what is the reason by communicating",
              "with others.Without communication, the society will be in a mess and there is no mutual trust between",
              "people. The harmonious society our Chinese government advocates is built up on the very basis of",
              "communication among our citizens.",
              "Therefore, everyone should devote himself to communicating with other sincerely as the",
              "communication is so important in our society.(191words)",
              "短文写作总分15分，此文得分12分，评分较为准确。此文总的来说写得还算不错。首先，结",
              "构合理，有头有尾，中间两段是正文。其次，内容较充实，正文一段重点讲交流有助于建立良好的人",
              "际关系乃至友谊，增强互信，便于交流真实的思想，找到共同的兴趣；另一段讲交流有利于解决争议",
              "和误解，可对事由做出好的判断，如果没有交流，社会将陷人混乱，人与人之间将没有信任，并认为",
