              "Passage Two",
              "Just as Mrs.Waldman hands out the spelling test,you see Jeff pull out a small piece of paper",
              "with a lot of words on it. Jeff hides the note into his closed fist but soon takes it out again. While he's",
              "taking the test, you see him looking back and forth between the teacher and his paper. There's no",
              "mistaking ithe's cheating.",
              "Cheating is when a person misleads, deceives, or acts dishonestly on purpose. For kids, cheating",
              "may happen at school, at home, or while playing a sport. If a baseball team is for kids who are 8 or",
              "younger, it's cheating for a 9-year-old to play on the team.",
              "At school, in addition to cheating on a test, a kid might cheat by stealing someone else's idea for",
              "a science project or by copying a book report off the Internet and turning it in as if it's his or her",
              "original work.",
              "One is inclined to cheat because it makes difficult things seem easy, like getting all the right",
              "answers on the test. But it doesn't solve the problem of not knowing the material and it won't help on",
              "the next testunless the person cheats again.",
              "Sometimes it may seem like cheaters have it all figured out. They can watch TV instead of study-",
              "ing for the spelling test. But other people lose respect for cheaters and think less of them. The cheaters",
              "themselves may feel bad because they know they are not really earning that good grade. And, if they",
              "试题一<<<89",
              "get caught cheating, they will be in trouble at school, and maybe at home, too.",
              "Some kids cheat because they're busy or lazy and they want to get good grades without spending",
              "the time studying. Other kids might feel like they can't pass the test without cheating. Even when there",
              "seems to be a “good reason\" for cheating, cheating isn't a good idea.",
              "16. Why did Jeff look at the teacher from time to time while taking the test?",
              "A. He was afraid that the teacher might find out what he was doing.",
              "B. He had a question for the teacher but was afraid to ask.",
              "C. He wanted to get the teacher's attention.",
              "D. He wanted to hand in his paper as he was done with it.",
              "17. According to the author, cheating.",
              "A. occurs mainly in test-related settings",
              "B. can take on various forms and happen anywhere",
              "C. usually happens when one is doing a science project",
              "D. happens when we don't know the answer to a question",
              "18. What can't cheating help to do?",
              "A. To pass examinations.",
              "B. To get a satisfactory score.",
              "C. To make difficult things easy.",
              "D. To really get the knowledge.",
              "19. Which of the following statements is closest in meaning to “cheaters have it all figured out\"",
