              "Passage Three",
              "One of my favorite posters says, “Life is a test. It is only a test. Had this been a real life you",
              "wisdom, it reminds me not to take my life so seriously.",
              "When you look at life and its many challenges as a test, or series of tests, you begin to see each",
              "issue you face as an opportunity to grow, a chance to discover more about life. Whether you are",
              "90>>>第三部分练习试题及解析",
              "confronted with problems, responsibilities or hardships, when looking at them as a test, you always",
              "have a chance to succeed. If, on the other hand, you see each new issue you face as a serious battle",
              "that must be won in order to survive, you are probably in for a very rocky journey.",
              "As an experiment, see if you can apply this idea to something you are forced to deal with. Perhaps",
              "you have much pressure from your parents or a demanding boss. See if you can redefine the issue from",
              "being a “problem\"” to being a test. Rather than struggle with your issue, see if there is something you",
              "can learn from it. Ask yourself:“Can I see it as a test of something kind?\"",
              "If you try this strategy you may be surprised at your changed responses. For example, I used to",
              "struggle a great deal over the issue of my perception of not having enough time. I would rush around",
              "trying to get everything done. I blamed my schedule, my family, my circumstances, and anything else",
              "I could think of for my bad situation. Then it dawned on me that my real challenge was to see my",
              "struggle as a test. Seeing this issue as a test finally helped me to cope with one of my biggest personal",
              "frustrations. It has become far more acceptable to me to take things as they are.",
              "21. The author suggests that people",
              "A. take life seriously",
              "B. take life humorously",
              "C. see life as a test",
              "D. see life as a battle",
