              "试题一<<<91",
              "Passage Four",
              "Psychologists tell us that there are four basic stages that human beings pass through when they",
              "enter and live in a new culture. This process, which helps us to deal with culture shock, is the way",
              "our brain and our personality reacts to the strange new things we encounter when we move from one",
              "culture to another. If the language we use when talking to someone in our own culture is influenced by",
              "levels of formality based on the other person's age and status, it may be difficult for us to feel",
              "comfortable communicatingwith people in the new culture.",
              "Culture begins with the “honeymoon stage\". This is the period of time when we first arrive in",
              "which everything about the new culture is strange and exciting. This honeymoon stage can last for quite",
              "a long time because we feel we are involved in some kind of great adventure.",
              "Unfortunately,the second stage of culture shock can be more difficult.After we have settled down",
              "into our new life, working or studying, buying groceries, doing laundry, or living with a home-stay",
              "family, we can become very tired and begin to miss our homeland and our family, girlfriend/boyfriend,",
              "pets. This stage is considered a crisis in the process of cultural adjustment and many people choose to",
              "go back to their homeland or spend all their time with people from their own culture speaking their",
              "native language.",
              "The third stage of culture shock is called the“adjustment stage\". This is when you begin to",
              "realize that things are not so bad in the host culture. Your sense of humor usually becomes stronger and",
              "you realize that you are becoming stronger by learning to take care of yourself in the new place. Things",
              "are still difficult, but you are now a survivor!",
              "The fourth stage can be called“at ease at last\".Now you feel quite comfortable in your new",
              "surroundings. You can cope with most problems that occur.You may still have problems with the",
              "language, but you know you are strong enough to deal with them.",
              "There is a fifth stage of culture shock which many people don't know about. This is called",
              "“\"reverse culture shock\". Surprisingly, this occurs when you go back to your native culture and find",
              "that you have changed and that things there have changed while you have been away. Now you feel a",
              "little uncomfortable back home.",
              "26.When does culture shock happen?",
              "A. When you go back to your own culture after quite a while.",
              "B. When you read a culture very different from your own.",
              "C. When you have grown tired of your own culture.",
              "D.When you first come into contact with a new culture.",
              "27. How do you feel during the first stage of culture shock?",
              "A. Lonely and depressed.",
              "B.Bored and indifferent.",
              "C. Happy and excited.",
              "D. Angry and frustrated.",
              "28. People in the second stage of culture shock may probably",
              "A. choose to spend all their time with people from their homeland",
              "92>>>第三部分练习试题及解析",
              "B.try to mix with the people they are now living with",
              "C. may develop unhealthy habits like smoking and drinking",
