              "参考译文",
              "[1］目前最广为认可的理论认为，戏剧是从仪式演化而来。",
              "[2］有些做法似乎产生了期待的结果，就被保留下来并不断重复，从而积淀下来成为不变的仪式。",
              "[3］认为戏剧从仪式演化而来的人们还指出，之所以说这些仪式包含了戏剧的胚胎（元",
              "素），是因为它们几乎总是运用音乐、舞蹈、面具和服饰。",
              "[4】他们经常戴着面具，穿着专门服饰扮演其他人物、动物或超自然生灵，模仿所期待的效",
              "果，比如打到了猎物，打了胜仗，大雨将至，太阳复活等一一所有这些都和演员的表演相类似。",
              "[5］另一个理论则认为，戏剧起源于人们对讲故事的兴趣。",
              "Part VWriting (30 minutes,15 points)",
              "参考作文",
              "Dear Ms. Zhang,",
              "I'm Wang Rui, a student who has enrolled in your evening course“\"Spoken English\". I'm sorry to",
              "inform you that I won't be able to continue your course due to some unforeseen circumstances.One of",
              "my regular daytime courses in my major has been moved to the evening.The timing is in conflict with",
              "your course.So I can do nothingbut back out.",
              "However, I hope to take your course some other time, in next semester,for example, if your",
              "course happens to be in the schedule. Meanwhile I would like you to give me some advice about how to",
              "improve my spoken English, if that does not cause you too much trouble. I hope that we can keep in",
              "touch through e-mail.",
              "sincerely yours",
              "Wang Rui",
              "96>>>第三部分、练习试题及解析",
              "试题一解析",
              "PartIDialogueCompletion（完成对话）",
              "对话一",
              "本段对话是医院里探视病人的对话。再看选项，见有一个问句、3个陈述句。本段要求用完",
              "所有选项。",
              "空格1：答案D",
              "空格1处是女士（探望者）说话。之后，男士第二次表示感谢。按常理，病人对探望者表示",
              "感谢，那一定是后者带来了礼物之类。选项D.Ibroughtyousomeflowers，andaget-wellcard正",
              "是此意，应是答案。其他选项不符合情景。",
              "空格2：答案A",
              "男士询问其他人（同事或朋友）怎么样，空格2处是女士的回答。这通常是常规的、礼节性",
              "的回答。选项A.Theyaredoingfine符合要求，是答案。",
              "空格3：答案B",
              "空格3后男士说了句It'snottoobad（“还凑合吧”），显然是对女士某个问题的回答。选项B",
              "是问句，符合此处的意义，因此是答案。",
              "空格4：答案C",
              "空格4前的Notreally（“不常去”）是对女士询问是否“经常去图书馆”的回答。这里的内容",
              "显然是解释为什么不经常去的原因。选项只剩下了C，见它的意思是：“它在医院的另一边”，正",
              "是不经常去的原因，因此是答案。",
              "对话二",
              "整段是关于求职面试中的一段对话，Mr.Johnson是求职者，Mr.Smith是雇主。4个选项中",
              "有两个问句、两个陈述句。注意本段有一个多余选项。",
              "空格5：答案D",
              "空格5后是Mr.Johnson的回答：Yes.Thatworksverywellforme（“是的，对我来说非常合",
              "适”），可见空格要求填入问句。看选项，见D.Doesthatwork foryou？符合问句要求，且意义也",
              "合适，因此是答案。",
              "空格6：答案A",
              "答，只有选项A是回答，意义正好合适，因此是答案。",
              "空格7：答案C",
              "面试到此已基本结束。雇主告知求职者何时听候结果后，空格7处该是求职者致谢告别了。",
              "选项C符合要求，因此是答案。",
              "试题一<<<97",
              "对话三",
              "整段对话是关于周末到乡间度假。选项中有两个问句、两个陈述句。本段也有一个多余",
              "选项。",
              "空格8：答案D",
              "话题首先由David提起，问Frank“周末干什么？”（第一行）Frank在回答“没有什么打算”的",
              "同时，觉得David发问必有缘故，因此这里的内容应是他的疑问，选项D符合要求，因此是答案。",
              "空格9：答案A",
              "此处内容应是David对Frank“Who else isgoing?”（“还有谁去”）的回答，因此选项A是",
              "答案。",
              "空格10：答案B",
              "在David对周末丰富多彩的活动做了一番描述后，此处应是Frank的回应。选项B.Ilove",
              "marshmallows（“我喜欢棉花糖”）正好是对David最后一句提到的marshmallows的回应，语气上还",
              "表达了他很憧憬的样子，与下文David的发问“Soyouwill comethen?”也能衔接，因为David感到",
              "了Frank愿意与他同去乡下。因此选项B是答案。选项C是个问句，与空格后的问句相冲突，可",
              "以排除。",
              "PartIⅡReadingComprehension（阅读理解）",
              "第一篇",
              "本文讲述了一个儿子不孝敬老人，却在听到自已儿子（老人孙子）的无意话语后转变态度和",
              "做法的故事。故事中的儿子认识到自已怎样对待父母，将来自己的孩子就会怎样对待自己，从此",
              "后就学会了孝敬老人。",
              "11.答案：B",
              "解析：第一段描述了过去几代人住在一起并不是不寻常的事情。这里几代人指的就是祖父",
              "母、父母和孙辈住在一起。",
              "12.答案：C",
              "解析：第二段说儿媳妇不喜欢老公公，认为他总是碍事，所以坚持让他住在家外面的屋子里。",
              "13．答案：A",
              "解析：倒数第二段说小孩让爸爸把毯子一分为二，一半给爷爷，另一半留着给爸爸。等到爸",
              "爸像爷爷那么老时就可以把这一半给他，这样爸爸就不会觉得冷了。",
              "14.答案：B",
              "解析：最后一段说小孩的话让儿子认识到他没有好好对待自已的父亲。从此以后他把老父",
              "亲接回家里，学会了善待老人。因为他认识到自已怎样对待父亲，孩子将来就会怎样对待自已。",
              "15.答案：D",
