              "PartVWriting（短文写作）",
              "这是2009年6月的写作考题，当年规定的长度要求是100到120词之间，略高于新《大纲》",
              "的要求。现在看来，设置120词的上限是没有必要的，考生完全可以写得长一些。",
              "考题要求考生写一封信给有关老师，说明自已因故不能继续修习某晚间课程，请求在其他时",
              "间再修。考题指示是英文的，且比较详细，有些词汇考生可借鉴使用。",
              "参考作文在第一段通知老师不能继续修习英语口语课了，原因是原本白天上课的专业课程",
              "有一门移到了晚上，时间上与口语课发生冲突，因此只能不上口语课了。这是事先没想到的情况",
              "（unforeseencircumstances）。文章的第二段话锋一转（注意用However），告诉老师想在下一个学",
              "期再修英语口语课，前提是该课程在新学期的课程表上有安排。此外想让老师出出主意，怎样改",
              "进英语口语，当然不希望给老师添很多麻烦（notcause youtoomuchtrouble）。最后希望与老师用",
              "电子邮件保持联系。",
              "这样的信不难写，格式规范好把握，语言也比较简单。当然，英文要写得地道就不是件容易",
              "的事了。考生可以摩一下参考作文的一些用语和结构，如timing、someothertime、happentobe、",
              "meanwhile连接词和if条件句等的使用。",
