              "解析：本题是语法题，兼考worth的用法。无论表达主动还是被动的意义，worth后都跟主动",
              "态的动名词。知道这一点，就知道正确答案是D。全句的意思是：“值得记住的是，即便是最复杂",
              "的科学思想最终都会影响我们的日常生活。”",
              "46.答案：B",
              "解析：本题考的是定语从句和degree的用法。事情达到或以某种程度发生用tothedegree，",
              "120>>>第三部分练习试题及解析",
              "degree可带定语从句做主语，后面的关系代词必须带to，因此选项B.towhich是答案。tothat不",
              "能引导定语从句，其他选项没有to。全句的意思是：“你保持心理健康的程度可能取决于某些简",
              "单的环境因素。”",
              "47.答案：A",
              "解析：本题是语法题。英语描述两个紧接着发生的事件，说前一件几乎还没完后一件就发生",
              "了，极言其快，前一事件的小句用hardly、scarcely和barely引导，后一事件的小句用when引出，形",
              "成相配的结构。因此选项A是答案。选项B.than也用于表述后面的事件，但与Nosooner引导",
              "的前句配对。全句的意思是：“他们进电影院还未坐稳当电影就开始了。”",
              "48.答案：D",
              "解析：本题是语法题和词汇题的结合，难度较大。首先要知道“be said+各类动词不定式”的",
              "意思是“某人或某事被传说..”；其次是要分析时态，按照本句中的时间状语right now和后面",
              "半句的意思，这里需要的是现在进行时态的不定式；再者要看语态，因为This project(“项目”）是",
              "主语，谈及它的carryout“执行”）应用被动语态。符合现在进行时的被动语态不定式只有选项",
              "D，因此D是答案。全句的意思是：“据说该项目正在进行之中，而且到目前为止一切都很顺利。”",
              "49.答案：D",
              "解析：本题是语法题，难度较大。全句的意思是：“一般认为，比起其他任何发明，互联网更",
              "何发明”)之间的比较，注意不能丢了other，否则不能表达“其他”的意思；其次是要知道，句子想",
              "表达“互联网”强于“其他任何发明”的意思，需要用morethan，而不仅仅是than。凭这两条就可",
              "排除干扰项A、B、C,得到答案D。has与后面主语倒装是习惯用法。",
              "50.答案：A",
              "解析：本题是语法也是词汇题，考的是whatever和worth的用法。选项B.However（“无论怎",
