              "PartVWriting(短文写作）",
              "这是一个图表解读题，要求考生根据图中的标题及其中的数据，挖掘信息，写出短文。这样",
              "的短文可以是研究报告、学术论文、统计公告或新闻报道的一部分。",
              "图表解读在很多时候要进行比较，不仅仅是做简单的描述。本书第二部分第五章举了一个",
              "有关电子书和印刷书的使用偏好的例子。那个例子的比较是跨类的，类别就是书的用途。而现",
              "在这张图有关三个产品全年的销售情况，是由折线而不是条形表示的。这里的比较，不仅要做产",
              "品间跨类的比较，更重要的是要做跨时间的比较，即对比每个产品在各个月份的销售情况。从图",
              "中可以看出，这种比较可从横和竖两个维度来进行。",
              "参考作文开头用一句话概括了该图的内容。虽然标题表述的也是同样的信息，但正文还是",
              "122>>>第三部分练习试题及解析",
              "要这样开始，不能突元地直接就进行描述和比较。",
              "参考作文用3段分别描述了产品X、Y和乙在全年的销售情况。考生应注意，这里的关键是",
              "怎样用英文表达“增长、下降、持平、波动”等概念，如使用rise、increase、fall、decline、stabilize、",
              "fluctuate等语汇和有关的句型；还要会用一些修饰语，如sharp、sharply、marked、steady、steadily、",
              "slightly等。",
              "参考作文在描述各产品跨月销售情况的同时，也在产品间进行了比较。例如：Comparedwith",
              "the other two products, this one showed the greatest growth in sales over the last 12 months(\"与其他",
              "两种产品比较，本产品年终比年初销售量增加的幅度最大”）；再如：ThesalesofProductZshowed",
              "theleastvariationoverthe12months（“产品Z的销售量在全年波动的幅度最小”）。",
              "考生可能已经注意到，参考作文没有结尾段，但这不影响短文的完整性，因为表格的信息已",
              "基本报告完毕，如果没有特别突出的、总的信息可以概括，这样做也是可以的。",
              "描述并报告该图提供的信息，参考作文并不是唯一的形式或最好的总结，英文也未必是最纯",
              "正的。考生可以根据本书附录二提供的英文表达方式，试着用多种句式和表达方式练习，力争在",
              "逻辑和语言上比参考作文做得更好。",
