              "参考译文",
              "我始终不明白为什么那么多人热衷于见名人。在朋友面前吹嘘自已认识某某名人，唯一的",
              "他们向世人展示的是面具，一张常常是美好难忘的面具，而把真实的面貌小心翼翼地掩盖起来。",
              "他们只是表演公众期待的角色，表演多了，终能驾轻就熟。如果以为名人们在公众面前的这种表",
              "演就是他们真实的自我，你可就犯傻了。",
              "Part VWriting(30 minutes,15 points)",
              "参考作文",
              "What I Think of the Chinese Dream",
              "The concept of \"Chinese Dream\"represents a set of ideals shared by both the leadership and the",
              "general public. The ideals may mean\"re-emergence of China\", as officials put it. To me,however,the",
              "Chinese Dream may translate into realistic goals pursued by us ordinary citizens.",
              "Then what are some of the goals we are pursuing? Today,we are looking for things that are more",
              "than just pocketbook. We have a richer conception of what a good life means : we want to live in a place",
              "feel worried when we are ill or as we grow old. Our children can receive good education and get jobs",
              "when they grow up. There is fair play in competition and justice in court rulings. These goals should be",
              "fully covered by the ideals which are described as the Chinese Dream.",
              "To sum up,it is the realistic goals held by the masses that form the basis of the Chinese Dream",
              "and thus merit more serious attention.",
