              "对话一",
              "整段对话是有关绿色、环保的话题。选项有两个问句、两个陈述句。本段要求用完4个",
              "选项。",
              "空格1：答案D",
              "Frank对David说他的公司已开始采取更环保的措施，空格1的内容是David的回应。选项",
              "A比较具体，不是所需要的一般性的回应；选项B是后半句话，并是问句，也不合适；选项C.",
              "Really表示惊奇或疑惑，也不切题。只有选项D.Metoo（“我也是\"）符合要求，因此是答案。",
              "空格2：答案A",
              "David说“他们家开始不用商店的塑料袋而是自带口袋去购物”，空格2的内容是Frank的回",
              "应。浏览选项，见有两个选项A和B可选，选项B中的“省钱”似乎与“带口袋购物”有些联系，",
              "但代词he及问句形式都与上下文不符；而选项A“那是减少消耗的好方式”很切合题意，因此是",
              "答案。“减少消耗”是指塑料袋的“消耗”。",
              "空格3：答案B",
              "Frank谈到他的同事有一辆使用天然气的小车，David回应说他听说那种小车便宜多了，空",
