              "对话二",
              "对话是有关业余爱好的。4个选项有两个问句、两个陈述句。本段有一多余选项。",
              "空格5：答案C",
              "\"：Andrew说“喜欢建造模型火车和汽车”，Bert在空格5处进行回应，而下文是Andrew肯定的",
