              "PartⅡIReadingComprehension(阅读理解)",
              "第一篇",
              "本文介绍了就业的新趋势，根据联合国国际劳工组织（ILO）的数据，目前服务业的从业人数",
              "首次超过了制造业的人数。文章分析了部分的原因并介绍了服务业的现状以及存在的问题。",
              "11.答案：C",
              "解析：第四段前两句介绍了ValdirdeSantos的情况。他认为开出租车比种地轻松，但是他接",
              "触的都只是低收入的工作。",
              "12.答案：D",
              "解析：第四段最后一句说，ILO担心的是发展中国家的许多工作者仍然没有得到充分的",
              "利用。",
              "13.答案：B",
              "解析：第五段说每个国家都仍然需要低收入和高技能的工作者。但是收入是由提供服务的",
              "技能水平决定的。",
              "14.答案：A",
              "解析：第六段说随着服务成为可交易的产品，工作者将面临海外的竞争。经济学家Alan",
              "要在客户眼前服务的工作者来说，他们的就业可能无法得到保障。也就是说，他们更有可能面临",
              "试题三<<<135",
              "海外的竞争。",
              "15.答案：A",
              "解析：本文主要介绍经济领域的新变化，历史上第一次服务业的从业人员超过了制造业的",
              "人数。",
              "第二篇",
              "本文强调了工作是一种家庭责任。父母努力工作为子女创造身心健康成长的环境，父母也",
              "会期望子女努力工作，承担应有的家庭责任。",
              "16.答案：B",
              "解析：第一段提到工作是一种家庭责任。你正在从父母的工作中获益，他们的工作为你提供",
              "了身心健康的条件。他们也希望你能够分担这样的家庭责任。",
              "17.答案：D",
              "亲人，并告诉他们：“如果没有家人的支持，你们今天就不会得到这样的荣誉。”",
              "18.答案:C",
              "解析：第二段最后三句说现在希望，甚至要求你们为自已的孩子和家庭提供类似的支持。这",
              "就意味着不能再“闲逛”了。长大后，父母希望你能够自已养自己，能够独立。",
              "19.答案：B",
              "解析：第三段最后一句说，那些从小就被父母教导要努力工作的人能够证明工作对人生的价",
              "值。testimony的意思是证明。",
              "20.答案：A",
              "解析：作者在文章中反复强调的就是工作的重要性，特别是工作对承担家庭责任的重要性。",
              "最后一段说在你的生活中可能经历一些困难，但认识到工作对家庭的重要性就会帮助你战胜这",
              "些困难。",
              "第三篇",
              "本文介绍了世界上有很多语言正在逐渐消失。作者分析了这些语言消失的原因，认为我们",
              "有理由保护这些临灭绝的语言，拯救这些语言的希望在于年轻人愿意学习并传承这些语言及",
              "代表的文化。",
              "21.答案：D",
              "解析：第一段说现在世界上的7000种语言中超过一半正面临消失的危险。但不是说历史",
              "上总共存在过7000种语言，所以C是错误的。最后一段说保护这些濒临消失的语言的希望在",
              "于年轻人愿意学习并传承它们，说明还是有希望让这些语言保留下来的，所以A和B是错误的。",
              "22.答案：B",
              "解析：文章第二、三段提到了官方语言。第二段最后一句说官方语言代表了控制一群人的一",
              "种形式。第三段最后一句说强势文化的语言具有更大的影响力，一些小的文化社会就会失去自",
              "已的语言。而官方语言通常都是强势文化的语言。",
              "23.答案：A",
              "136>>>第三部分练习试题及解析",
              "解析：第四、五段讲述了为什么语言是通向思想和世界的窗户。第四段说语言中涵盖了一种",
              "文化的历史、思想和知识，还包括了有关医药和动植物的有用信息。第五段特别强调一些濒临消",
              "失的语言代表的文化往往和自然界具有亲密的关系，所以这些语言中包含了有关环境和动植物",
