export const DEGREE_KNOWLEDGE_FLAT: DegreeKnowledgeLesson[] = DEGREE_BOOKS.flatMap((b) =>
  b.chapters.flatMap((c) =>
    c.lessons.map((l) => ({ ...l, _book: b.name, _bookId: b.id, _chapter: c.title, _chapterId: c.id }))
  )
)
